add_filter( 'avatar_defaults', 'perfectpixel_custom_default_avatar_option' );
add_filter( 'pre_option_avatar_default', 'perfectpixel_custom_default_avatar_selected' );

function perfectpixel_custom_default_avatar_url() {
	return esc_url_raw( trim( '{{custom_avatar_url}}' ) );
}

function perfectpixel_custom_default_avatar_option( $defaults ) {
	$url = perfectpixel_custom_default_avatar_url();
	if ( $url ) {
		$defaults[ $url ] = '{{custom_avatar_label}}';
	}
	return $defaults;
}

function perfectpixel_custom_default_avatar_selected( $value ) {
	$url = perfectpixel_custom_default_avatar_url();
	return $url ? $url : $value;
}
